package in.kalaimarket;
import java.math.BigDecimal;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.web.server.ResponseStatusException;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class BrokerLedgerServiceTest {
 @Test void duplicateDealUsesStableAccountServerTicketKeyAndKeepsLink(){var e=mock(DemoExecutionService.class);when(e.getAccount()).thenReturn(123456L);when(e.getServer()).thenReturn("OctaFX-Demo");var repo=mock(BrokerDealRepository.class);var sync=mock(BrokerSyncRepository.class);var claims=mock(BrokerExecutionRepository.class);var claim=new BrokerExecution();claim.accountLogin=123456;claim.brokerServer="OctaFX-Demo";when(claims.findBySignalId(7L)).thenReturn(Optional.of(claim));var retained=new BrokerDeal();when(repo.findById("123456:OctaFX-Demo:100")).thenReturn(Optional.of(retained));var svc=new BrokerLedgerService(e,repo,sync,claims);var now=Instant.now();var d=new LedgerRequest.Deal(100,900,901,7L,now,"XAUUSD",1,1,5,new BigDecimal(".01"),new BigDecimal("110"),new BigDecimal("3"),new BigDecimal("-.2"),new BigDecimal("-.1"),new BigDecimal("-.01"));var r=new LedgerRequest("11111111-1111-4111-8111-111111111111",123456,"OctaFX-Demo",now,now,List.of(d),List.of(),BigDecimal.TEN,BigDecimal.TEN);svc.ingest(r);svc.ingest(r);assertEquals("123456:OctaFX-Demo:100",retained.id);assertEquals(7L,retained.signalId);assertEquals(0,new BigDecimal("2.69").compareTo(retained.getNet()));verify(repo,times(2)).save(retained);}
 @Test void wrongAccountCannotImportAnything(){var e=mock(DemoExecutionService.class);when(e.getAccount()).thenReturn(123456L);var repo=mock(BrokerDealRepository.class);var svc=new BrokerLedgerService(e,repo,mock(BrokerSyncRepository.class),mock(BrokerExecutionRepository.class));var now=Instant.now();assertThrows(ResponseStatusException.class,()->svc.ingest(new LedgerRequest("11111111-1111-4111-8111-111111111111",999,"OctaFX-Demo",now,now,List.of(),List.of(),BigDecimal.TEN,BigDecimal.TEN)));verify(repo,never()).save(any());}
}
